function renderBoardMap(list=filteredJobs()){if(boardView!=='map')return;initBoardMap();if(!boardMap)return;boardMapLayer.clearLayers();const points=[];list.forEach(job=>{if(!Number.isFinite(job.lat)||!Number.isFinite(job.lng))return;points.push([job.lat,job.lng]);const value=job.rate*(job.end-job.start);L.circleMarker([job.lat,job.lng],{radius:10,color:'#0e1418',weight:3,fillColor:'#f0a400',fillOpacity:1}).bindPopup(`<div class="map-job-popup"><strong>${job.role}</strong><span>${job.company} · ${job.area}</span><small>${job.date}, ${job.time} · ${value} zł</small><button type="button" onclick="openJob(${job.id})">Zobacz ofertę →</button></div>`).addTo(boardMapLayer)});setTimeout(()=>{boardMap.invalidateSize();if(points.length===1)boardMap.setView(points[0],13);else if(points.length)boardMap.fitBounds(points,{padding:[35,35],maxZoom:13})},60)}
