function renderFilterSummary(){const chips=[];if(aiMatchedIds!==null)chips.push('Wybrane przez AI');if(locationFilterEnabled)chips.push(`Lokalizacja · do ${filters.radius} km`);if(filters.minRate)chips.push(`Od ${filters.minRate} zł/h`);if(filters.industries.length)chips.push(`${filters.industries.length} rodzaje pracy`);if(filters.time!=='all')chips.push({morning:'Rano',afternoon:'Popołudnie',evening:'Wieczór'}[filters.time]);if(filters.noExperience)chips.push('Bez doświadczenia');if(filters.noEnglish)chips.push('Bez angielskiego');if(filters.trainingProvided)chips.push('Szkolenie na miejscu');if(filters.lightWork)chips.push('Praca lekka');if(filters.outfitProvided)chips.push('Strój zapewniony');if(filters.sameDayPay)chips.push('Wypłata dziś');if(filters.noQualifications)chips.push('Bez uprawnień');document.querySelector('#activeFilters').innerHTML=chips.map(x=>`<span class="filter-chip">${x}</span>`).join('');const badge=document.querySelector('#filterCount');badge.textContent=chips.length;badge.classList.toggle('visible',chips.length>0);const bar=document.querySelector('.location-bar');bar.classList.toggle('inactive',!locationFilterEnabled);document.querySelector('#locationLabel').textContent=locationFilterEnabled?`${userLocation.label} · do ${filters.radius} km`:'Lokalizacja wyłączona';document.querySelector('#clearLocation').hidden=!locationFilterEnabled;document.querySelector('#mapClearLocation').hidden=!locationFilterEnabled}
function openJob(id){const j=jobs.find(x=>x.id===id),d=getJobDetails(j),pay=j.rate*(j.end-j.start);const publicPart=`<div class="modal-hero" style="background:${j.color}"><div class="company-logo">${j.icon}</div><p class="eyebrow">${j.match}% DOPASOWANIA · ${jobDistance(j).toFixed(1).replace('.',',')} KM</p><h2>${j.role}</h2><p>${j.company} · ${j.area}</p></div><div class="modal-body"><div class="modal-details"><div class="detail"><small>Kiedy</small><strong>${j.date}<br>${j.time}</strong></div><div class="detail"><small>Wynagrodzenie</small><strong>${pay} zł<br>${j.rate} zł/h</strong></div></div>`;if(!authUser){jobModal.querySelector('#modalContent').innerHTML=publicPart+`<div class="guest-job-preview"><h3>Informacje ogólne</h3><p>Krótka, elastyczna zmiana w dzielnicy ${j.area}. Dokładny adres, kontakt do pracodawcy, obowiązki i instrukcje organizacyjne są dostępne po zalogowaniu.</p><div class="locked-details"><div class="lock-icon">🔒</div><strong>Szczegóły dostępne po zalogowaniu</strong><p>Założenie konta jest bezpłatne i nie zobowiązuje Cię do przyjęcia zmiany.</p></div><button class="login-details-button">Zaloguj się i zobacz szczegóły</button></div></div>`;jobModal.showModal();jobModal.querySelector('.login-details-button').onclick=()=>openAuth('login',()=>openJob(id));return}jobModal.querySelector('#modalContent').innerHTML=publicPart+`<div class="details-section"><h3>Miejsce i kontakt</h3><div class="private-details-grid"><div class="private-detail wide"><small>DOKŁADNY ADRES</small><strong>⌖ ${d.address}</strong></div><div class="private-detail"><small>OSOBA KONTAKTOWA</small><strong>${d.contactName}</strong></div><div class="private-detail"><small>TELEFON SŁUŻBOWY</small><strong><a href="tel:${d.contactPhone.replace(/\s/g,'')}">${d.contactPhone}</a></strong></div></div></div><div class="details-section"><h3>Przygotowanie do zmiany</h3><div class="instruction-list"><div class="instruction-row"><span>◷</span><div><strong>Przyjście</strong><small>${d.arrival}</small></div></div><div class="instruction-row"><span>♙</span><div><strong>Strój</strong><small>${d.dressCode}</small></div></div><div class="instruction-row"><span>▤</span><div><strong>Dokumenty</strong><small>${d.documents}</small></div></div><div class="instruction-row"><span>ⓘ</span><div><strong>Dodatkowe informacje</strong><small>${d.instructions}</small></div></div></div></div><div class="details-section"><h3>Zakres obowiązków</h3><ul>${j.tasks.map(t=>`<li>${t}</li>`).join('')}</ul><p><strong>Wymagania:</strong> ${requirementLabel(j)}</p></div><button class="book-button" data-book="${j.id}">${booked.includes(j.id)?'Anuluj zapis':'Biorę tę zmianę'}</button><p class="details-notice">Klikając przycisk, potwierdzasz znajomość szczegółów i gotowość do realizacji zmiany.</p></div>`;jobModal.showModal();jobModal.querySelector('[data-book]').onclick=()=>toggleBook(id)}
function toggleBook(id){booked=booked.includes(id)?booked.filter(x=>x!==id):[...booked,id];localStorage.setItem('flexo-booked',JSON.stringify(booked));jobModal.close();renderJobs();renderBooked();renderDashboardSummary();toast(booked.includes(id)?'Zmiana jest Twoja! Szczegóły znajdziesz w kalendarzu.':'Zapis na zmianę został anulowany.')}
function workerShiftDateParts(job){const date=nextShiftDate(job),locale=currentLanguage==='en'?'en-GB':'pl-PL';return{weekday:new Intl.DateTimeFormat(locale,{weekday:'short'}).format(date).replace('.','').toUpperCase(),dayMonth:new Intl.DateTimeFormat(locale,{day:'numeric',month:'short'}).format(date).replace('.','').toUpperCase()}}
function renderBooked(){const list=booked.map(id=>jobs.find(j=>j.id===id)).filter(Boolean);document.querySelector('#shiftCount').textContent=list.length;document.querySelector('#bookedList').innerHTML=list.length?list.map(j=>`<article class="booked-card"><div class="date-tile"><small>${workerShiftDateParts(j).weekday}</small><strong>${workerShiftDateParts(j).dayMonth}</strong></div><div class="grow"><h3>${j.role}</h3><p>${j.company} · ${j.time} · ${j.area}</p><strong>${j.rate*(j.end-j.start)} zł</strong></div><button class="primary" onclick="openJob(${j.id})">Szczegóły</button></article>`).join(''):'<div class="empty">Nie masz jeszcze zaplanowanych zmian.</div>'}
function switchView(id){if(id==='admin'&&authUser?.role!=='admin'){toast('Panel administratora jest dostępny tylko dla administratorów.');id='discover'}if(id==='employer'&&!['employer','admin'].includes(authUser?.role)){toast('Panel pracodawcy wymaga konta firmowego.');id='discover'}document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active-view',v.id===id));document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===id));window.scrollTo({top:0,behavior:'smooth'})}
function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3200)}
function locateUser(showMapAfter=false){const status=document.querySelector('#geoStatus');status.textContent='Pobieram lokalizację…';if(!navigator.geolocation)return toast('Ta przeglądarka nie obsługuje geolokalizacji.');navigator.geolocation.getCurrentPosition(p=>{userLocation={lat:p.coords.latitude,lng:p.coords.longitude,label:'Twoja lokalizacja'};locationFilterEnabled=true;status.textContent=`Dokładność: ${Math.round(p.coords.accuracy)} m`;renderJobs();if(showMapAfter){if(filterModal.open)filterModal.close();if(!document.querySelector('#mapModal').open)openMap()}if(jobsMap){jobsMap.setView([userLocation.lat,userLocation.lng],13);updateMap()}toast('Lokalizacja została ustawiona — wybierz ofertę na mapie.')},()=>{status.textContent='Brak dostępu';toast('Zezwól przeglądarce na dostęp do lokalizacji.')},{enableHighAccuracy:true,timeout:10000,maximumAge:300000})}
function syncFilterForm(){document.querySelector('#radiusInput').value=filters.radius;document.querySelector('#radiusOutput').value=filters.radius;document.querySelector(`[name="rate"][value="${filters.minRate}"]`).checked=true;document.querySelectorAll('[name="industry"]').forEach(x=>x.checked=filters.industries.includes(x.value));document.querySelector('#timeFilter').value=filters.time;['noExperience','noEnglish','trainingProvided','lightWork','outfitProvided','sameDayPay','noQualifications'].forEach(key=>document.querySelector(`#${key}`).checked=!!filters[key])}
