function renderExtendedProfile(){const section=document.querySelector('#profile');if(!section)return;let box=section.querySelector('.extended-profile-data');if(!box){box=document.createElement('div');box.className='extended-profile-data';section.appendChild(box)}const taxLabels={standard:'Standardowy',student_u26:'Uczeń / student do 26 lat',employment_min:'Umowa o pracę — co najmniej minimalne wynagrodzenie',other_contract:'Inny tytuł do ubezpieczeń',business:'Działalność gospodarcza',pension:'Emeryt / rencista',verify:'Wymaga weryfikacji'},restrictionLabels={noHeavyLifting:'Bez podnoszenia ciężarów',noAlcohol:'Bez serwowania alkoholu',noNight:'Bez pracy nocnej',limitedStanding:'Bez długiego stania',indoorOnly:'Tylko praca wewnątrz',noCustomerFacing:'Bez obsługi klientów'};box.innerHTML=`<div><small>LOKALIZACJA I DZIELNICE</small><strong>${userProfile.city||'Nie wybrano'}</strong><p>${(userProfile.districts||[]).join(', ')||'Brak wybranych dzielnic'}</p></div><div><small>PREFERENCJE I OGRANICZENIA</small><strong>${(userProfile.workRestrictions||[]).map(x=>restrictionLabels[x]).join(', ')||'Brak ograniczeń'}</strong><p>${userProfile.workNotes||'Brak dodatkowych informacji'}</p></div><div><small>STATUS ROZLICZENIOWY</small><strong>${taxLabels[userProfile.taxStatus]||'Nie uzupełniono'}</strong><p>Deklaracja wymaga potwierdzenia przed umową.</p></div><div><small>RACHUNEK DO WYPŁATY</small><strong>${maskedBankAccount(userProfile.bankAccount)}</strong><p>${userProfile.bankHolder||'Nie podano właściciela rachunku'}</p></div>`}function renderProfile(){renderGreeting();document.querySelectorAll('.profile-avatar').forEach(x=>x.textContent=initials());document.querySelector('#profileFullName').textContent=`${userProfile.firstName} ${userProfile.lastName}`;document.querySelector('#profileCity').textContent=userProfile.city;document.querySelector('#profileBio').textContent=userProfile.bio||'Dodaj kilka słów o sobie.';document.querySelector('#profileEmail').textContent=userProfile.email;document.querySelector('#profilePhone').textContent=userProfile.phone;document.querySelector('#profileIndustries').textContent=userProfile.industries||'Nie wybrano';document.querySelector('#profileSkills').innerHTML=userProfile.skills.map(x=>`<span>${x}</span>`).join('');renderAuthState()}
