function populateProfileCompletion(user){const form=document.querySelector('#profileCompletionForm');if(!form||!user)return;form.workerCity.value=user.city||'Warszawa';renderRegistrationDistricts(form.workerCity.value);setCheckedValues(form,'districts',user.districts||[]);setCheckedValues(form,'preferredIndustries',user.preferredIndustries||[]);const predefined=[...form.querySelectorAll('[name="workerSkills"]')].map(x=>x.value),custom=(user.skills||[]).filter(x=>!predefined.includes(x));setCheckedValues(form,'workerSkills',user.skills||[]);form.customSkill.value=custom.join(', ');form.workerMinRate.value=user.minRate||'';form.workerTime.value=user.preferredTime||'all';setCheckedValues(form,'workerPreferences',user.preferences||[]);setCheckedValues(form,'workRestrictions',user.workRestrictions||[]);form.workNotes.value=user.workNotes||'';form.taxStatus.value=user.taxStatus||'standard';form.bankHolder.value=user.bankHolder||'';form.bankAccount.value=user.bankAccount||'';form.resetSkillLogic?.()}
