function saveProfile(form){const d=new FormData(form);userProfile={firstName:d.get('firstName').trim(),lastName:d.get('lastName').trim(),city:d.get('city').trim(),email:d.get('email').trim(),phone:d.get('phone').trim(),bio:d.get('bio').trim(),skills:d.get('skills').split(',').map(x=>x.trim()).filter(Boolean),industries:d.get('industries').trim(),photo:pendingProfilePhoto||''};localStorage.setItem('flexo-profile',JSON.stringify(userProfile));renderProfile();document.querySelector('#profileModal').close();toast('Profil został zaktualizowany.')}
