function setupProfilePhoto(){const content=document.querySelector('#profileForm .form-content'),box=document.createElement('section');box.className='profile-photo-editor';box.innerHTML='<div class="avatar large photo-preview"></div><div><strong>Zdjęcie profilowe</strong><p>Zdjęcie jest wymagane tylko przy zgłoszeniach do ofert oznaczonych jako customer-facing.</p><label class="photo-upload">📷 Zrób zdjęcie aparatem<input class="profile-photo-input" type="file" accept="image/*" capture="user"></label><label class="photo-upload gallery">▧ Wybierz z galerii<input class="profile-photo-input" type="file" accept="image/jpeg,image/png,image/webp"></label><button type="button" class="remove-photo">Usuń zdjęcie</button></div>';content.prepend(box);const inputs=[...box.querySelectorAll('.profile-photo-input')],preview=box.querySelector('.photo-preview');inputs.forEach(input=>input.onchange=()=>processProfilePhoto(input.files[0],photo=>{pendingProfilePhoto=photo;setPhotoPreview(preview,photo)}));box.querySelector('.remove-photo').onclick=()=>{pendingProfilePhoto='';inputs.forEach(input=>input.value='');setPhotoPreview(preview,'')};const originalOpen=openProfileEditor;openProfileEditor=function(){originalOpen();pendingProfilePhoto=userProfile.photo||'';setPhotoPreview(preview,pendingProfilePhoto)};const modal=document.createElement('dialog');modal.id='photoRequiredModal';modal.className='photo-required-modal';modal.innerHTML='<button class="modal-close" aria-label="Zamknij">×</button><form id="photoRequiredForm"><input type="hidden" name="jobId"><div class="photo-required-icon">◎</div><p class="eyebrow">OFERTA CUSTOMER-FACING</p><h2>Ta rola wymaga zdjęcia profilowego</h2><p data-photo-job></p><div class="photo-required-info">Pracodawca zobaczy zdjęcie podczas oceny kandydatury. Nie używamy automatycznej analizy twarzy ani wyglądu.</div><div class="photo-required-upload"><div class="avatar large photo-preview"></div><div class="photo-required-actions"><label class="photo-upload">📷 Zrób zdjęcie aparatem<input class="required-photo-input" type="file" accept="image/*" capture="user"></label><label class="photo-upload gallery">▧ Wybierz z galerii<input class="required-photo-input" type="file" accept="image/jpeg,image/png,image/webp"></label></div></div><label class="terms-check"><input name="consent" type="checkbox" required><span>Zgadzam się na udostępnienie zdjęcia pracodawcy w ramach tego zgłoszenia.</span></label><button class="candidate-confirm-main" type="submit">Zapisz zdjęcie i wyślij zgłoszenie</button><button class="photo-skip" type="button">Anuluj</button></form>';document.body.appendChild(modal);const requiredForm=modal.querySelector('form'),requiredPreview=modal.querySelector('.photo-preview');modal.querySelectorAll('.modal-close,.photo-skip').forEach(button=>button.onclick=()=>modal.close());requiredForm.querySelectorAll('.required-photo-input').forEach(input=>input.onchange=()=>processProfilePhoto(input.files[0],photo=>{requiredForm.dataset.photo=photo;setPhotoPreview(requiredPreview,photo)}));requiredForm.onsubmit=e=>{e.preventDefault();if(!requiredForm.dataset.photo||!requiredForm.consent.checked)return toast('Dodaj zdjęcie i zaakceptuj zgodę.');userProfile.photo=requiredForm.dataset.photo;localStorage.setItem('flexo-profile',JSON.stringify(userProfile));pendingProfilePhoto=userProfile.photo;const jobId=+requiredForm.jobId.value;modal.close();requiredForm.reset();delete requiredForm.dataset.photo;renderProfile();submitApplication(jobId)}}
