const CONTRACT_DRAFTS_KEY='flexo-contract-drafts';
function confirmedApplicationFor(jobId){return applications.find(a=>a.jobId===jobId&&['confirmed','completed','employer_issue'].includes(a.status))}
function decorateContractButtons(){document.querySelectorAll('#employerJobsList .admin-job-row,#adminJobsList .admin-job-row').forEach(row=>{if(row.querySelector('.contract-action'))return;const title=row.querySelector('strong')?.textContent,meta=row.querySelector('small')?.textContent,job=jobs.find(j=>j.role===title&&meta?.includes(j.company)),app=job&&confirmedApplicationFor(job.id);if(!app)return;const actions=row.querySelector('.admin-actions');if(!actions)return;const button=document.createElement('button');button.className='contract-action';button.title='Projekt umowy';button.textContent='§';button.onclick=()=>openContractDraft(job.id);actions.prepend(button)})}
function contractDraftData(job,app){const saved=JSON.parse(localStorage.getItem(CONTRACT_DRAFTS_KEY)||'{}')[job.id]||{},details=getJobDetails(job);return{employerName:saved.employerName||authUser?.companyName||job.company,employerAddress:saved.employerAddress||'',employerNip:saved.employerNip||authUser?.nip||'',employerRepresentative:saved.employerRepresentative||details.contactName,workerName:saved.workerName||app.workerName,workerAddress:saved.workerAddress||'',workerIdentifier:saved.workerIdentifier||'',place:saved.place||details.address,paymentDate:saved.paymentDate||'7 dni od zaakceptowania ewidencji godzin',hoursMethod:saved.hoursMethod||'podpisana przez strony karta wykonania zlecenia',extra:saved.extra||''}}
function openContractDraft(jobId){const job=jobs.find(j=>j.id===jobId),app=confirmedApplicationFor(jobId);if(!job||!app||!['employer','admin'].includes(authUser?.role)||!canManageJob(job))return toast('Projekt umowy jest dostępny po zaakceptowaniu pracownika.');const d=contractDraftData(job,app),form=document.querySelector('#contractDraftForm');form.jobId.value=jobId;Object.entries(d).forEach(([key,value])=>{if(form.elements[key])form.elements[key].value=value});document.querySelector('#contractDraftMatch').textContent=`${job.role} · ${app.workerName} · ${job.date}, ${job.time}`;renderContractPreview(jobId);document.querySelector('#contractDraftModal').showModal()}
function contractField(name){return document.querySelector('#contractDraftForm').elements[name]?.value.trim()||'________________'}
function renderContractPreview(jobId){const job=jobs.find(j=>j.id===+jobId),app=confirmedApplicationFor(+jobId);if(!job||!app)return;const bill=jobBilling(job),tasks=(job.tasks||[]).map(x=>`<li>${x}</li>`).join(''),today=new Intl.DateTimeFormat('pl-PL').format(new Date());document.querySelector('#contractPreview').innerHTML=`<div class="contract-paper"><p class="contract-kicker">PROJEKT ROBOCZY · WYGENEROWANO ${today}</p><h1>UMOWA ZLECENIA / ŚWIADCZENIA USŁUG</h1><p>zawarta pomiędzy <b>${contractField('employerName')}</b>, adres: ${contractField('employerAddress')}, NIP: ${contractField('employerNip')}, reprezentowanym przez ${contractField('employerRepresentative')}, dalej „Zleceniodawca”, a <b>${contractField('workerName')}</b>, adres: ${contractField('workerAddress')}, identyfikator uzupełniany bezpośrednio przez strony: ${contractField('workerIdentifier')}, dalej „Zleceniobiorca”.</p><h2>§1. Przedmiot i termin</h2><p>Zleceniobiorca zobowiązuje się świadczyć czynności związane ze zleceniem „${job.role}” w dniu ${job.date}, w godzinach ${job.time}, w miejscu: ${contractField('place')}.</p><ul>${tasks}</ul><p>Czynności mają charakter starannego działania. Strony potwierdzają, że rzeczywisty sposób współpracy odpowiada wybranej podstawie prawnej.</p><h2>§2. Wynagrodzenie i godziny</h2><p>Wynagrodzenie wynosi <b>${job.rate.toFixed(2).replace('.',',')} zł brutto za godzinę</b>. Szacunkowo za ${job.end-job.start} godz. wyniesie ${bill.unitValue.toFixed(2).replace('.',',')} zł brutto. Podstawą rozliczenia jest: ${contractField('hoursMethod')}. Zapłata nastąpi przelewem w terminie: ${contractField('paymentDate')}.</p><h2>§3. Wykonanie zlecenia</h2><p>Zleceniobiorca wykonuje czynności osobiście, z należytą starannością, przestrzega zasad bezpieczeństwa i niezwłocznie zgłasza przeszkody. Zleceniodawca zapewnia informacje, dostęp do miejsca oraz warunki niezbędne do bezpiecznego wykonania zlecenia.</p><h2>§4. Rozliczenia publicznoprawne</h2><p>Zleceniodawca ustala obowiązki podatkowe i ubezpieczeniowe na podstawie oświadczeń Zleceniobiorcy oraz obowiązujących przepisów i realizuje obowiązki płatnika, jeżeli powstaną.</p><h2>§5. Rezygnacja i odpowiedzialność</h2><p>Strony mogą wypowiedzieć zlecenie na zasadach wynikających z przepisów. Osoba wypowiadająca zlecenie bez ważnego powodu odpowiada za szkodę na zasadach przewidzianych prawem. Postanowienia platformy dotyczące anulowania nie wyłączają bezwzględnie obowiązujących praw stron.</p><h2>§6. Dane i poufność</h2><p>Strony wykorzystują dane otrzymane w związku ze zleceniem wyłącznie do jego wykonania i rozliczenia. Informacje organizacyjne oraz dane osób trzecich nie mogą być ujawniane bez podstawy prawnej.</p><h2>§7. Dodatkowe ustalenia</h2><p>${contractField('extra')}</p><h2>§8. Postanowienia końcowe</h2><p>W sprawach nieuregulowanych stosuje się właściwe przepisy prawa polskiego. Umowę sporządzono w dwóch jednobrzmiących egzemplarzach, po jednym dla każdej strony.</p><div class="contract-signatures"><span>_________________________<small>Zleceniodawca</small></span><span>_________________________<small>Zleceniobiorca</small></span></div></div>`}
