if(paymentModalV2){const form=paymentModalV2.querySelector('form');form.innerHTML='<input type="hidden" name="applicationId"><button type="button" class="modal-close" aria-label="Zamknij">×</button><div class="payment-icon">✓</div><p class="eyebrow">OPŁATA ZA MATCH</p><h2>Wybierz pracownika i opłać kontakt</h2><p class="payment-worker"><strong data-payment-worker></strong><span data-payment-job></span></p><div class="payment-summary"><div><span>Model cenowy</span><strong data-payment-tier></strong></div><div class="payment-total"><span>Opłata za tę osobę</span><strong data-payment-total></strong></div><div><span>Opłacone matche w tej ofercie</span><strong data-payment-paid></strong></div><div class="payment-remaining"><span>Pozostały potencjalny koszt zespołu</span><strong data-payment-remaining></strong></div></div><div class="payment-demo-note"><strong>Match-only</strong><span>Płacisz wyłącznie stałą opłatę Temporeo za potwierdzony kontakt. Wynagrodzenie i umowę rozliczasz bezpośrednio z pracownikiem. Czas pracy nie wpływa na tę opłatę.</span></div><label class="terms-check"><input name="accept" type="checkbox" required><span>Akceptuję opłatę za potwierdzony match.</span></label><button type="submit" class="candidate-confirm-main" data-payment-submit></button><button type="button" class="photo-skip">Wróć do kandydatów</button>';form.querySelector('.modal-close').onclick=()=>paymentModalV2.close();form.querySelector('.photo-skip').onclick=()=>{paymentModalV2.close();const app=applications.find(item=>item.id===form.applicationId.value);if(app)openCandidates(app.jobId)};form.onsubmit=e=>{e.preventDefault();const app=applications.find(item=>item.id===form.applicationId.value),job=jobs.find(item=>item.id===app?.jobId);if(!app||!job)return paymentModalV2.close();const quote=matchFeeForJob(job);app.workerReserved=0;app.matchFee=quote.amount;app.fundedAmount=quote.amount;app.matchFeeTier=quote.tier;app.matchPaidAt=Date.now();app.paymentStatus='match_fee_paid_demo';saveApplications();paymentModalV2.close();finalizeCandidateMatch(app.id);toast(`Opłata za match ${quote.amount} zł została zapisana. Kontakt został odblokowany.`)}}
openMatchPayment=function(applicationId){const app=applications.find(item=>item.id===applicationId),job=jobs.find(item=>item.id===app?.jobId);if(!app||app.status!=='pending'||!job)return;const quote=matchFeeForJob(job),paid=paidMatchAmountV2(job.id),remainingAfter=Math.max(0,quote.amount*((job.positions||1)-filledPositions(job.id)-1)),modal=document.querySelector('#matchPaymentModal'),form=modal.querySelector('form');form.applicationId.value=applicationId;modal.querySelector('[data-payment-worker]').textContent=app.workerName;modal.querySelector('[data-payment-job]').textContent=`${job.role} · ${job.date}, ${job.time}`;modal.querySelector('[data-payment-tier]').textContent=quote.label;modal.querySelector('[data-payment-total]').textContent=`${quote.amount.toFixed(2).replace('.',',')} zł`;modal.querySelector('[data-payment-paid]').textContent=`${paid.toFixed(2).replace('.',',')} zł`;modal.querySelector('[data-payment-remaining]').textContent=`${remainingAfter.toFixed(2).replace('.',',')} zł`;modal.querySelector('[data-payment-submit]').textContent=`Opłać match ${quote.amount.toFixed(2).replace('.',',')} zł`;document.querySelector('#candidateProfileModal')?.close();document.querySelector('#candidatesModal')?.close();modal.showModal()};confirmCandidate=openMatchPayment;

