/* First come, first served: taking an open place confirms the shift immediately. */
const FIRST_COME_MIGRATION_KEY='temporeo-first-come-v1';
function matchFeeOnInstantBooking(job,app){const quote=matchFeeForJob(job);app.matchFee=quote.amount;app.fundedAmount=quote.amount;app.matchFeeTier=quote.tier;app.matchPaidAt=Date.now();app.paymentStatus='match_fee_charged_demo'}
function migratePendingApplicationsToFirstCome(){
 if(localStorage.getItem(FIRST_COME_MIGRATION_KEY))return;
 const grouped=new Map();applications.filter(app=>app.status==='pending').sort((a,b)=>a.appliedAt-b.appliedAt).forEach(app=>{if(!grouped.has(app.jobId))grouped.set(app.jobId,[]);grouped.get(app.jobId).push(app)});
 grouped.forEach((pending,jobId)=>{const job=jobs.find(item=>item.id===jobId);if(!job)return pending.forEach(app=>app.status='expired');let free=openPositions(job);pending.forEach(app=>{if(free>0){app.status='confirmed';app.confirmedAt=app.appliedAt||Date.now();delete app.deadline;matchFeeOnInstantBooking(job,app);free--}else app.status='rejected'})});
 saveApplications();localStorage.setItem(FIRST_COME_MIGRATION_KEY,'done');
}
