function crewRelation(employerEmail,workerEmail){return employerCrew.find(item=>item.employerEmail===employerEmail&&item.workerEmail===workerEmail)}
function favouriteRelation(workerEmail,employerEmail){return workerFavouriteEmployers.find(item=>item.workerEmail===workerEmail&&item.employerEmail===employerEmail)}
